INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (1, 6, 'Concurso Sefaz AL: SAIU EDITAL com 100 vagas!', 'Saiba tudo sobre o Concurso Sefaz AL e as oportunidades para Auditor Fiscal. Vagas confirmadas e edital em breve!
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (2, NULL, 'Concurso ISS Aracati: edital oferta 7 vagas para Auditor!', 'Um novo Concurso ISS Aracati, no Estado do Ceará, teve seu edital publicado com a oferta de 7 vagas. As oportunidades são para Auditor Fiscal, com exigência de formação. O salário inicial é de R$ 3.347,94, além de benefícios. Sob organização da banca FCPC, as inscrições poderão ser efetuadas entre os dias 24 de setembro [&#8230;]
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (3, 3, 'Edital Sefaz AL SAIU: 100 vagas e salário de R$ 25 mil!', 'O edital Sefaz AL 2026 foi publicado para o cargo de Auditor Fiscal da Administração Tributária Estadual (AFTE). A Secretaria de Estado da Fazenda de Alagoas oferece 100 vagas, sendo 40 imediatas e 60 para cadastro de reserva, com remuneração de R$ 25.270,68 e jornada de 40 horas semanais. A organização está sob responsabilidade do&#8230;', 'O edital Sefaz AL 2026 foi publicado para o cargo de Auditor Fiscal da Administração Tributária Estadual (AFTE). A Secretaria de Estado da Fazenda de Alagoas oferece 100 vagas, sendo 40 imediatas e 60 para cadastro de reserva, com remuneração de R$ 25.270,68 e jornada de 40 horas semanais. A organização está sob responsabilidade do&#8230;', 'https://blog.grancursosonline.com.br/concurso-sefaz-al-edital-publicado-2026/', 'Gran Cursos Online', 'estadual', 'SP', 'Previsto / Em Estudos', '2026-08-25 10:16:58', TRUE, '2026-08-25 10:29:34', '{"sigla":"SEFAZ-SP","orgao":"Secretaria da Fazenda e Planejamento de S\u00e3o Paulo","cargo":"Auditor Fiscal da Receita Estadual (AFRE)","inicial_bruto":31200,"vencimento_base":15234,"produtividade":15966,"produtividade_info":"Pr\u00eamio de Produtividade (PR) e Quotas Fiscais (Resolu\u00e7\u00f5es SF). Os auditores em exerc\u00edcio na SEFAZ-SP atingem rapidamente remunera\u00e7\u00f5es reais brutas acima de R$ 33.000,00 at\u00e9 o teto estadual.","beneficios":1800,"beneficios_info":"Aux\u00edlio Refei\u00e7\u00e3o (R$ 55,00\/dia), Aux\u00edlio Transporte, Adicional de Qualifica\u00e7\u00e3o e Gratifica\u00e7\u00e3o de Desempenho.","real_transparencia":36500,"teto":44008.52,"banca":"Vunesp \/ FGV \/ FCC (em defini\u00e7\u00e3o)","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:22:16', '2026-08-25 10:29:34') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (4, 1, 'Concursos Fiscais 2026: previsões e ganhos de até R$ 37 mil!', 'Deseja conquistar uma vaga nos concursos fiscais em 2026? A Receita Federal é o principal destaque do período: o concurso foi autorizado com 146 vagas, e a etapa de planejamento para escolha da banca já começou. O edital deve ser publicado até 3 de janeiro de 2027. Outros certames estaduais também avançaram. A SEFAZ DF&#8230;', 'Deseja conquistar uma vaga nos concursos fiscais em 2026? A Receita Federal é o principal destaque do período: o concurso foi autorizado com 146 vagas, e a etapa de planejamento para escolha da banca já começou. O edital deve ser publicado até 3 de janeiro de 2027. Outros certames estaduais também avançaram. A SEFAZ DF&#8230;', 'https://blog.grancursosonline.com.br/concursos-fiscais/', 'Gran Cursos Online', 'federal', 'DF', 'Autorizado', '2026-08-24 19:11:05', TRUE, '2026-08-26 08:58:08', '{"sigla":"RFB - Auditor","orgao":"Receita Federal do Brasil (AFRFB)","cargo":"Auditor-Fiscal da Receita Federal do Brasil","inicial_bruto":24823.11,"vencimento_base":22921.71,"produtividade":3000,"produtividade_info":"B\u00f4nus de Efici\u00eancia e Produtividade Tribut\u00e1ria e Aduaneira (Lei n\u00ba 13.464\/2017 e Decreto n\u00ba 11.936\/2024), pago a partir do 13\u00ba m\u00eas de efetivo exerc\u00edcio, podendo chegar a mais de R$ 11.500,00 no topo.","beneficios":1000,"beneficios_info":"Aux\u00edlio Alimenta\u00e7\u00e3o (R$ 1.000,00), Aux\u00edlio Pr\u00e9-Escolar (R$ 484,90 por dependente), Aux\u00edlio Sa\u00fade Suplementar e Adicional Noturno\/Fronteira (R$ 91,00\/dia trabalhado em postos de fronteira).","real_transparencia":27500,"teto":44008.52,"banca":"FGV (\u00faltima) \/ Em defini\u00e7\u00e3o","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:22:16', '2026-08-26 08:58:08') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (5, 3, 'Concurso SEFAZ SP: Comissão avança nos estudos para 250 vagas de Auditor Fiscal com inicial de R$ 31.200', 'A Secretaria da Fazenda de São Paulo trabalha nos preparativos do novo concurso para Auditor Fiscal da Receita Estadual (AFRE). A remuneração real com Prêmios de Produtividade (PR) ultrapassa R$ 35.000,00 no Portal da Transparência.', 'A Secretaria da Fazenda de São Paulo trabalha nos preparativos do novo concurso para Auditor Fiscal da Receita Estadual (AFRE). A remuneração real com Prêmios de Produtividade (PR) ultrapassa R$ 35.000,00 no Portal da Transparência.', 'https://radar.financeiro.local/noticias/sefaz-sp-comissao-avanca-2026', 'Radar Fiscal', 'estadual', 'SP', 'Comissão Formada', '2026-08-25 02:40:45', TRUE, '2026-08-26 08:58:14', '{"sigla":"SEFAZ-SP","orgao":"Secretaria da Fazenda e Planejamento de S\u00e3o Paulo","cargo":"Auditor Fiscal da Receita Estadual (AFRE)","inicial_bruto":31200,"vencimento_base":15234,"produtividade":15966,"produtividade_info":"Pr\u00eamio de Produtividade (PR) e Quotas Fiscais (Resolu\u00e7\u00f5es SF). Os auditores em exerc\u00edcio na SEFAZ-SP atingem rapidamente remunera\u00e7\u00f5es reais brutas acima de R$ 33.000,00 at\u00e9 o teto estadual.","beneficios":1800,"beneficios_info":"Aux\u00edlio Refei\u00e7\u00e3o (R$ 55,00\/dia), Aux\u00edlio Transporte, Adicional de Qualifica\u00e7\u00e3o e Gratifica\u00e7\u00e3o de Desempenho.","real_transparencia":36500,"teto":44008.52,"banca":"Vunesp \/ FGV \/ FCC (em defini\u00e7\u00e3o)","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:58:14') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (6, 4, 'Concurso SEFAZ RJ: Escolha da banca organizadora entra na fase final para 195 vagas', 'O concurso da Secretaria de Estado de Fazenda do Rio de Janeiro está na fase de contratação da banca examinadora. São 45 vagas imediatas e 150 em cadastro de reserva para Auditor e Analista, com inicial de R$ 29.420,00.', 'O concurso da Secretaria de Estado de Fazenda do Rio de Janeiro está na fase de contratação da banca examinadora. São 45 vagas imediatas e 150 em cadastro de reserva para Auditor e Analista, com inicial de R$ 29.420,00.', 'https://radar.financeiro.local/noticias/sefaz-rj-banca-fase-final-2026', 'Radar Fiscal', 'estadual', 'RJ', 'Banca Definida', '2026-08-23 19:40:45', TRUE, '2026-08-26 08:58:02', '{"sigla":"SEFAZ-RJ","orgao":"Secretaria de Estado de Fazenda do Rio de Janeiro","cargo":"Auditor Fiscal da Receita Estadual (AFRE)","inicial_bruto":29420,"vencimento_base":13186.76,"produtividade":16233.24,"produtividade_info":"Gratifica\u00e7\u00e3o de Produtividade Fiscal (GDA) e Participa\u00e7\u00e3o no Resultado da Arrecada\u00e7\u00e3o. Grande parte dos auditores ativos atinge o teto do governador\/STF.","beneficios":1500,"beneficios_info":"Aux\u00edlio Refei\u00e7\u00e3o e Transporte.","real_transparencia":34200,"teto":44008.52,"banca":"Cebraspe \/ FGV (em fase final)","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:58:02') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (7, 1, 'Receita Federal: Novo pedido para mais de 2.000 vagas de Auditor e Analista tramita no MGI', 'A Receita Federal do Brasil mantém sob análise do Ministério da Gestão e da Inovação o pedido para abertura de novo concurso público. O Bônus de Eficiência regulamentado garante remunerações acima de R$ 27.000,00.', 'A Receita Federal do Brasil mantém sob análise do Ministério da Gestão e da Inovação o pedido para abertura de novo concurso público. O Bônus de Eficiência regulamentado garante remunerações acima de R$ 27.000,00.', 'https://radar.financeiro.local/noticias/receita-federal-pedido-vagas-mgi-2026', 'Radar Fiscal', 'federal', 'DF', 'Solicitado', '2026-08-24 01:40:45', TRUE, '2026-08-26 08:58:04', '{"sigla":"RFB - Auditor","orgao":"Receita Federal do Brasil (AFRFB)","cargo":"Auditor-Fiscal da Receita Federal do Brasil","inicial_bruto":24823.11,"vencimento_base":22921.71,"produtividade":3000,"produtividade_info":"B\u00f4nus de Efici\u00eancia e Produtividade Tribut\u00e1ria e Aduaneira (Lei n\u00ba 13.464\/2017 e Decreto n\u00ba 11.936\/2024), pago a partir do 13\u00ba m\u00eas de efetivo exerc\u00edcio, podendo chegar a mais de R$ 11.500,00 no topo.","beneficios":1000,"beneficios_info":"Aux\u00edlio Alimenta\u00e7\u00e3o (R$ 1.000,00), Aux\u00edlio Pr\u00e9-Escolar (R$ 484,90 por dependente), Aux\u00edlio Sa\u00fade Suplementar e Adicional Noturno\/Fronteira (R$ 91,00\/dia trabalhado em postos de fronteira).","real_transparencia":27500,"teto":44008.52,"banca":"FGV (\u00faltima) \/ Em defini\u00e7\u00e3o","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:58:04') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (8, 28, 'Concurso ISS Curitiba: Comissão trabalha no termo de referência para Auditor Fiscal', 'A Prefeitura Municipal de Curitiba avança nos trâmites do novo concurso de Auditor Fiscal de Tributos Municipais. Inicial de R$ 23.500,00 com gratificações e exigência de nível superior.', 'A Prefeitura Municipal de Curitiba avança nos trâmites do novo concurso de Auditor Fiscal de Tributos Municipais. Inicial de R$ 23.500,00 com gratificações e exigência de nível superior.', 'https://radar.financeiro.local/noticias/iss-curitiba-comissao-termo-referencia-2026', 'Radar Fiscal', 'municipal', 'PR', 'Comissão Formada', '2026-08-23 17:40:45', TRUE, '2026-08-26 08:57:59', '{"sigla":"ISS-Curitiba","orgao":"Secretaria Municipal de Planejamento, Finan\u00e7as e Or\u00e7amento de Curitiba","cargo":"Auditor Fiscal de Tributos Municipais","inicial_bruto":23500,"vencimento_base":12800,"produtividade":10700,"produtividade_info":"Gratifica\u00e7\u00e3o de Produtividade Fiscal e Quotas Municipais.","beneficios":1500,"beneficios_info":"Aux\u00edlio Refei\u00e7\u00e3o e Transporte.","real_transparencia":27000,"teto":37000,"banca":"NC-UFPR \/ FCC \/ FGV (em defini\u00e7\u00e3o)","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:57:59') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (9, 7, 'Concurso SEFAZ PR: Secretário da Fazenda confirma novo edital para Auditores com remuneração de R$ 28.500', 'A Fazenda do Paraná prepara o concurso para reposição urgente de auditores fiscais aposentados. Remunerações iniciais atrativas com plano de carreira atualizado.', 'A Fazenda do Paraná prepara o concurso para reposição urgente de auditores fiscais aposentados. Remunerações iniciais atrativas com plano de carreira atualizado.', 'https://radar.financeiro.local/noticias/sefaz-pr-secretario-confirma-edital-2026', 'Radar Fiscal', 'estadual', 'PR', 'Comissão Formada', '2026-08-25 03:40:45', TRUE, '2026-08-26 08:58:17', '{"sigla":"SEFAZ-PR","orgao":"Secretaria da Fazenda do Estado do Paran\u00e1","cargo":"Auditor Fiscal da Receita Estadual (AFRE)","inicial_bruto":28500,"vencimento_base":12540,"produtividade":15960,"produtividade_info":"Gratifica\u00e7\u00e3o de Produtividade Fiscal e Quotas de Arrecada\u00e7\u00e3o. Remunera\u00e7\u00e3o real m\u00e9dia passa de R$ 32.000,00.","beneficios":1600,"beneficios_info":"Aux\u00edlio Refei\u00e7\u00e3o e Transporte.","real_transparencia":33500,"teto":44008.52,"banca":"FGV \/ Cebraspe \/ FCC (em defini\u00e7\u00e3o)","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:58:17') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (10, 43, 'Concurso ISS Osasco: Polo de fintechs e gigantes de tecnologia prepara concurso para Auditor Tributário', 'Com forte arrecadação advinda do setor de tecnologia e pagamentos digitais, o município de Osasco-SP tem comissão formada para preencher vagas de Auditor Fiscal com remuneração acima de R$ 25.400.', 'Com forte arrecadação advinda do setor de tecnologia e pagamentos digitais, o município de Osasco-SP tem comissão formada para preencher vagas de Auditor Fiscal com remuneração acima de R$ 25.400.', 'https://radar.financeiro.local/noticias/iss-osasco-polo-fintechs-edital-2026', 'Radar Fiscal', 'municipal', 'SP', 'Comissão Formada', '2026-08-24 18:40:45', TRUE, '2026-08-26 08:58:06', '{"sigla":"ISS-Osasco","orgao":"Secretaria de Finan\u00e7as de Osasco","cargo":"Auditor Fiscal Tribut\u00e1rio","inicial_bruto":25400,"vencimento_base":7900,"produtividade":17500,"produtividade_info":"Gratifica\u00e7\u00e3o de Produtividade Fiscal de Osasco (polo nacional de fintechs, e-commerce e bancos digitais como Mercado Livre, Nubank, iFood e Bradesco).","beneficios":1600,"beneficios_info":"Aux\u00edlio Refei\u00e7\u00e3o e Transporte.","real_transparencia":29200,"teto":37000,"banca":"Vunesp (\u00faltima) \/ Em defini\u00e7\u00e3o","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:58:06') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (11, 10, 'SEFAZ GO: Estudos para 200 vagas de Auditor Fiscal da Receita Estadual avançam no estado', 'A Secretaria da Economia de Goiás intensificou os estudos orçamentários para novo concurso público para Auditor-Fiscal. Inicial passa de R$ 30.500,00 com prêmio de produtividade.', 'A Secretaria da Economia de Goiás intensificou os estudos orçamentários para novo concurso público para Auditor-Fiscal. Inicial passa de R$ 30.500,00 com prêmio de produtividade.', 'https://radar.financeiro.local/noticias/sefaz-go-estudos-200-vagas-auditor-2026', 'Radar Fiscal', 'estadual', 'GO', 'Comissão Formada', '2026-08-25 01:40:45', TRUE, '2026-08-26 08:58:10', '{"sigla":"SEFAZ-GO","orgao":"Secretaria de Estado da Economia de Goi\u00e1s","cargo":"Auditor-Fiscal da Receita Estadual (AFRE)","inicial_bruto":30500,"vencimento_base":20940.62,"produtividade":9559.38,"produtividade_info":"Gratifica\u00e7\u00e3o de Est\u00edmulo \u00e0 Arrecada\u00e7\u00e3o e Pr\u00eamio de Produtividade.","beneficios":1500,"beneficios_info":"Aux\u00edlio Alimenta\u00e7\u00e3o e Transporte.","real_transparencia":34000,"teto":44008.52,"banca":"FCC (\u00faltima) \/ Em defini\u00e7\u00e3o","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:58:10') ON CONFLICT (id) DO NOTHING;
INSERT INTO "fiscal_noticias" ("id", "fiscal_concurso_id", "titulo", "resumo", "conteudo", "url", "fonte", "esfera", "uf", "status_detectado", "publicado_em", "notificado_telegram", "notificado_em", "dados_remuneracao_snapshot", "created_at", "updated_at") VALUES (12, 54, 'Concurso ISS Aracati: Edital publicado com 7 vagas para Auditor Fiscal e remuneração real de até R$ 15 mil', 'A Prefeitura de Aracati-CE abriu concurso público com 7 vagas para Auditor Fiscal de Tributos Municipais pela banca FCPC. Inicial do edital de R$ 3.347,94 somado a gratificações de produtividade que atingem até R$ 15.000,00 no Portal da Transparência.', 'A Prefeitura de Aracati-CE abriu concurso público com 7 vagas para Auditor Fiscal de Tributos Municipais pela banca FCPC. Inicial do edital de R$ 3.347,94 somado a gratificações de produtividade que atingem até R$ 15.000,00 no Portal da Transparência.', 'https://radar.financeiro.local/noticias/concurso-iss-aracati-edital-fcpc-2026', 'Radar Fiscal / FCPC', 'municipal', 'CE', 'Edital Publicado', '2026-08-23 15:40:45', TRUE, '2026-08-26 08:57:57', '{"sigla":"ISS-Aracati","orgao":"Prefeitura Municipal de Aracati (Secretaria de Finan\u00e7as)","cargo":"Auditor Fiscal de Tributos Municipais","inicial_bruto":9847.94,"vencimento_base":3347.94,"produtividade":6500,"produtividade_info":"Gratifica\u00e7\u00e3o de Produtividade Fiscal e Desempenho Tribut\u00e1rio. Embora o edital traga o vencimento b\u00e1sico de R$ 3.347,94, dados do Portal da Transpar\u00eancia de Aracati mostram que os auditores fiscais recebem remunera\u00e7\u00f5es brutas reais entre R$ 7.500,00 e R$ 15.200,00 somando gratifica\u00e7\u00f5es e metas de arrecada\u00e7\u00e3o do ISS.","beneficios":1000,"beneficios_info":"Aux\u00edlio Alimenta\u00e7\u00e3o, Aux\u00edlio Transporte e Adicional de Titula\u00e7\u00e3o (Especializa\u00e7\u00e3o \/ Mestrado).","real_transparencia":12500,"teto":22000,"banca":"FCPC (Funda\u00e7\u00e3o Cearense de Pesquisa e Cultura)","requisito":"N\u00edvel Superior em qualquer \u00e1rea de forma\u00e7\u00e3o"}', '2026-08-25 10:40:45', '2026-08-26 08:57:57') ON CONFLICT (id) DO NOTHING;
